window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-003"]={"DEPDC7":{"coreEvidence":[{"partner":"RBBP5","hgnc":"HGNC:9888","core":true,"core_annotation":{"hgnc":"HGNC:9888","symbol_at_source":"RBBP5","accession":"Q15291","function":"Histone modification write cofactor","target":"histone","pmids":["19556245"],"complexes":"COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":385,"hub_weight":0.3390317518104052,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"In embryonic stem (ES) cells, plays a crucial role in the differentiation potential, particularly along the neural lineage, regulating gene induction and H3 'Lys-4' methylation at key developmental loci, including that mediated by retinoic acid (By similarity). Does not affect ES cell self-renewal (By similarity). Component or associated component of some histone methyltransferase complexes which regulates transcription through recruitment of those complexes to gene promoters (PubMed:19131338). As part of the MLL1/MLL complex, involved in mono-, di- and trimethylation at 'Lys-4' of histone H3 (PubMed:19556245). Histone H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:19556245). In association with ASH2L and WDR5, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"},{"partner":"TLE1","hgnc":"HGNC:11837","core":true,"core_annotation":{"hgnc":"HGNC:11837","symbol_at_source":"TLE1","accession":"Q04724","function":"Chromatin remodeling, Histone modification cofactor","target":"histone","pmids":["9334241","17041588"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":342,"hub_weight":0.35714285714285715,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional corepressor that binds to a number of transcription factors. Inhibits NF-kappa-B-regulated gene expression. Inhibits the transcriptional activation mediated by FOXA2, and by CTNNB1 and TCF family members in Wnt signaling. Enhances FOXG1/BF-1- and HES1-mediated transcriptional repression (By similarity). The effects of full-length TLE family members may be modulated by association with dominant-negative AES. Unusual function as coactivator for ESRRG","source":"project UniProt records20261017/18"},{"partner":"TLE2","hgnc":"HGNC:11838","core":true,"core_annotation":{"hgnc":"HGNC:11838","symbol_at_source":"TLE2","accession":"Q04725","function":"Histone modification cofactor","target":"histone","pmids":["17041588"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":289,"hub_weight":0.3840476863212843,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional corepressor that binds to a number of transcription factors. Inhibits the transcriptional activation mediated by CTNNB1 and TCF family members in Wnt signaling. The effects of full-length TLE family members may be modulated by association with dominant-negative AES (By similarity)","source":"project UniProt records20261017/18"},{"partner":"WDR82","hgnc":"HGNC:28826","core":true,"core_annotation":{"hgnc":"HGNC:28826","symbol_at_source":"WDR82","accession":"Q6UXN9","function":"Histone modification write cofactor","target":"histone","pmids":["17355966"],"complexes":"COMPASS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":281,"hub_weight":0.38866103716823586,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory component of the SET1/COMPASS complex implicated in the tethering of this complex to transcriptional start sites of active genes (PubMed:17998332, PubMed:18838538, PubMed:20516061). Facilitates histone H3 'Lys-4' methylation (H3K4me) via recruitment of the SETD1A or SETD1B to the 'Ser-5' phosphorylated C-terminal domain (CTD) of RNA polymerase II large subunit (POLR2A) (PubMed:17998332, PubMed:18838538). Component of the PNUTS-PP1 protein phosphatase complex, a protein phosphatase 1 (PP1) complex that promotes RNA polymerase II transcription pause-release, allowing transcription elongation (PubMed:39603240, PubMed:39603239). PNUTS-PP1 also plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase (PubMed:20516061). Together with ZC3H4, but independently of the SET1 complex, part of a transcription termination checkpoint that promotes transcription termination of long non-coding RNAs (lncRNAs) (PubMed:33767452, PubMed:33913806). The transcription termination checkpoint is activated by the inefficiently spliced first exon of lncRNAs and promotes transcription termination of lncRNAs and their subsequent degradation by the exosome (PubMed:33767452)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PRR35":{"coreEvidence":[{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"},{"partner":"OIP5","hgnc":"HGNC:20300","core":true,"core_annotation":{"hgnc":"HGNC:20300","symbol_at_source":"OIP5","accession":"O43482","function":"Chromatin remodeling","target":"histone","pmids":["17199038"],"complexes":"Mis18","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for recruitment of CENPA to centromeres and normal chromosome segregation during mitosis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ARMCX4":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"H1-4","hgnc":"HGNC:4718","core":true,"core_annotation":{"hgnc":"HGNC:4718","symbol_at_source":"HIST1H1E","accession":"P10412","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":559,"hub_weight":0.2865341275306264,"quality":0.65,"programmes":["pubmed:39358380"],"pmids":["39358380"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:35581345, PubMed:40240600). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:35581345, PubMed:40240600, PubMed:40516528). Ability to associate with nucleosomes and compact chromatin depends on linker DNA length and trajectory (PubMed:35581345). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (PubMed:40240600)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MSANTD4":{"coreEvidence":[{"partner":"SMARCA4","hgnc":"HGNC:11100","core":true,"core_annotation":{"hgnc":"HGNC:11100","symbol_at_source":"SMARCA4","accession":"P51532","function":"Histone modification read, TF","target":"histone","pmids":["17582821"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, CREST-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":753,"hub_weight":0.24953256425297482,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:15075294, PubMed:29374058, PubMed:30339381, PubMed:32459350). Component of the CREST-BRG1 complex, a multiprotein complex that regulates promoter activation by orchestrating the calcium-dependent release of a repressor complex and the recruitment of an activator complex. In resting neurons, transcription of the c-FOS promoter is inhibited by SMARCA4-dependent recruitment of a phospho-RB1-HDAC repressor complex. Upon calcium influx, RB1 is dephosphorylated by calcineurin, which leads to release of the repressor complex. At the same time, there is increased recruitment of CREBBP to the promoter by a CREST-dependent mechanism, which leads to transcriptional activation. The CREST-BRG1 complex also binds to the NR2B promoter, and activity-dependent induction of NR2B expression involves the release of HDAC1 and recruitment of CREBBP (By similarity). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development, a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth. SMARCA4/BAF190A may promote neural stem cell self-renewal/proliferation by enhancing Notch-dependent proliferative signals, while concurrently making the neural stem cell insensitive to SHH-dependent differentiating cues (By similarity). Acts as a corepressor of ZEB1 to regulate E-cadherin transcription and is required for induction of epithelial-mesenchymal transition (EMT) by ZEB1 (PubMed:20418909). Binds via DLX1 to enhancers located in the intergenic region between DLX5 and DLX6 and this binding is stabilized by the long non-coding RNA (lncRNA) Evf2 (By similarity). Binds to RNA in a promiscuous manner (By similarity). In brown adipose tissue, involved in the regulation of thermogenic genes expression (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCB1","hgnc":"HGNC:11103","core":true,"core_annotation":{"hgnc":"HGNC:11103","symbol_at_source":"SMARCB1","accession":"Q12824","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":713,"hub_weight":0.2559898425245689,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of the BAF (hSWI/SNF) complex. This ATP-dependent chromatin-remodeling complex plays important roles in cell proliferation and differentiation, in cellular antiviral activities and inhibition of tumor formation. The BAF complex is able to create a stable, altered form of chromatin that constrains fewer negative supercoils than normal. This change in supercoiling would be due to the conversion of up to one-half of the nucleosomes on polynucleosomal arrays into asymmetric structures, termed altosomes, each composed of 2 histones octamers. Stimulates in vitro the remodeling activity of SMARCA4/BRG1/BAF190A. Involved in activation of CSF1 promoter. Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity). Plays a key role in cell-cycle control and causes cell cycle arrest in G0/G1","source":"project UniProt records20261017/18"},{"partner":"AURKA","hgnc":"HGNC:11393","core":true,"core_annotation":{"hgnc":"HGNC:11393","symbol_at_source":"AURKA","accession":"O14965","function":"Histone modification write","target":"histone","pmids":["12576638"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":603,"hub_weight":0.27671226645624275,"quality":0.65,"programmes":["pubmed:32989298"],"pmids":["32989298"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole; Cell projection, neuron projection; Cell projection, cilium; Cytoplasm, cytoskeleton, cilium basal body; Basolateral cell membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitotic serine/threonine kinase that contributes to the regulation of cell cycle progression (PubMed:11039908, PubMed:12390251, PubMed:17125279, PubMed:17360485, PubMed:18615013, PubMed:26246606). Associates with the centrosome and the spindle microtubules during mitosis and plays a critical role in various mitotic events including the establishment of mitotic spindle, centrosome duplication, centrosome separation as well as maturation, chromosomal alignment, spindle assembly checkpoint, and cytokinesis (PubMed:14523000, PubMed:26246606). Required for normal spindle positioning during mitosis and for the localization of NUMA1 and DCTN1 to the cell cortex during metaphase (PubMed:27335426). Required for initial activation of CDK1 at centrosomes (PubMed:13678582, PubMed:15128871). Phosphorylates numerous target proteins, including ARHGEF2, BORA, BRCA1, CDC25B, DLGP5, HDAC6, KIF2A, LATS2, NDEL1, PARD3, PPP1R2, PLK1, RASSF1, TACC3, p53/TP53 and TPX2 (PubMed:11551964, PubMed:14702041, PubMed:15128871, PubMed:15147269, PubMed:15987997, PubMed:17604723, PubMed:18056443, PubMed:18615013). Phosphorylates MCRS1 which is required for MCRS1-mediated kinetochore fiber assembly and mitotic progression (PubMed:27192185). Regulates KIF2A tubulin depolymerase activity (PubMed:19351716). Important for microtubule formation and/or stabilization (PubMed:18056443). Required for normal axon formation (PubMed:19812038). Plays a role in microtubule remodeling during neurite extension (PubMed:19668197). Also acts as a key regulatory component of the p53/TP53 pathway, and particularly the checkpoint-response pathways critical for oncogenic transformation of cells, by phosphorylating and destabilizing p53/TP53 (PubMed:14702041). Phosphorylates its own inhibitors, the protein phosphatase type 1 (PP1) isoforms, to inhibit their activity (PubMed:11551964). Inhibits cilia outgrowth (By similarity). Required for cilia disassembly via phosphorylation of HDAC6 and subsequent deacetylation of alpha-tubulin (PubMed:17604723, PubMed:20643351). Regulates protein levels of the anti-apoptosis protein BIRC5 by suppressing the expression of the SCF(FBXL7) E3 ubiquitin-protein ligase substrate adapter FBXL7 through the phosphorylation of the transcription factor FOXP1 (PubMed:28218735)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PROB1":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"CCNJL":{"coreEvidence":[{"partner":"CDK1","hgnc":"HGNC:1722","core":true,"core_annotation":{"hgnc":"HGNC:1722","symbol_at_source":"CDK1","accession":"P06493","function":"Histone modification write","target":"histone","pmids":["22509284"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":451,"hub_weight":0.3159120118032817,"quality":0.65,"programmes":["pubmed:36736316"],"pmids":["36736316"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Mitochondrion; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Plays a key role in the control of the eukaryotic cell cycle by modulating the centrosome cycle as well as mitotic onset; promotes G2-M transition via association with multiple interphase cyclins (PubMed:16407259, PubMed:16933150, PubMed:17459720, PubMed:18356527, PubMed:19509060, PubMed:19917720, PubMed:20171170, PubMed:20935635, PubMed:20937773, PubMed:21063390, PubMed:2188730, PubMed:23355470, PubMed:2344612, PubMed:23601106, PubMed:23602554, PubMed:25556658, PubMed:26829474, PubMed:27814491, PubMed:30139873, PubMed:30704899, PubMed:40440427). Phosphorylates PARVA/actopaxin, APC, AMPH, APC, ASB7, BARD1, Bcl-xL/BCL2L1, BRCA2, CALD1, CASP8, CDC7, CDC20, CDC25A, CDC25C, CC2D1A, CENPA, CSNK2 proteins/CKII, FZR1/CDH1, CDK7, CEBPB, CHAMP1, DMD/dystrophin, EEF1 proteins/EF-1, EZH2, KIF11/EG5, EGFR, FANCG, FOS, GFAP, GOLGA2/GM130, GRASP1, UBE2A/hHR6A, HIST1H1 proteins/histone H1, HMGA1, HIVEP3/KRC, UHRF1, KAT5, LMNA, LMNB, LBR, MKI67, LATS1, MAP1B, MAP4, MARCKS, MCM2, MCM4, MKLP1, MLST8, MYB, NEFH, NFIC, NPC/nuclear pore complex, PITPNM1/NIR2, NPM1, NCL, NUCKS1, NPM1/numatrin, ORC1, PRKAR2A, EEF1E1/p18, EIF3F/p47, p53/TP53, NONO/p54NRB, PAPOLA, PLEC/plectin, RB1, TPPP, UL40/R2, RAB4A, RAP1GAP, RBBP8/CtIP, RCC1, RPS6KB1/S6K1, KHDRBS1/SAM68, ESPL1, SKI, BIRC5/survivin, STIP1, TEX14, beta-tubulins, MAPT/TAU, NEDD1, VIM/vimentin, TK1, FOXO1, RUNX1/AML1, SAMHD1, SIRT2, CGAS, GLI2 and RUNX2 (PubMed:16407259, PubMed:16933150, PubMed:17459720, PubMed:18356527, PubMed:19202191, PubMed:19509060, PubMed:19917720, PubMed:20171170, PubMed:20935635, PubMed:20937773, PubMed:21063390, PubMed:2188730, PubMed:22411829, PubMed:23355470, PubMed:2344612, PubMed:23601106, PubMed:23602554, PubMed:25012651, PubMed:25556658, PubMed:26829474, PubMed:27814491, PubMed:30704899, PubMed:31279575, PubMed:32351706, PubMed:34741373, PubMed:40440427). CDK1/CDC2-cyclin-B controls pronuclear union in interphase fertilized eggs (PubMed:18480403, PubMed:20360007). Essential for early stages of embryonic development (PubMed:18480403, PubMed:20360007). During G2 and early mitosis, CDC25A/B/C-mediated dephosphorylation activates CDK1/cyclin complexes which phosphorylate several substrates that trigger at least centrosome separation, Golgi dynamics, nuclear envelope breakdown and chromosome condensation (PubMed:18480403, PubMed:20360007, PubMed:2188730, PubMed:2344612, PubMed:30139873). Once chromosomes are condensed and aligned at the metaphase plate, CDK1 activity is switched off by WEE1- and PKMYT1-mediated phosphorylation to allow sister chromatid separation, chromosome decondensation, reformation of the nuclear envelope and cytokinesis (PubMed:18480403, PubMed:20360007). Phosphorylates KRT5 during prometaphase and metaphase (By similarity). Activated by the CDK-activating kinase (CAK) complex consisting of CDK7, cyclin-H/CCNH and MAT1, which is a master regulator of CDK activity (PubMed:41100585). Inactivated by PKR/EIF2AK2- and WEE1-mediated phosphorylation upon DNA damage to stop cell cycle and genome replication at the G2 checkpoint thus facilitating DNA repair (PubMed:20360007). Reactivated after successful DNA repair through WIP1-dependent signaling leading to CDC25A/B/C-mediated dephosphorylation and restoring cell cycle progression (PubMed:20395957). Catalyzes lamin (LMNA, LMNB1 and LMNB2) phosphorylation at the onset of mitosis, promoting nuclear envelope breakdown (PubMed:2188730, PubMed:2344612, PubMed:37788673). In proliferating cells, CDK1-mediated FOXO1 phosphorylation at the G2-M phase represses FOXO1 interaction with 14-3-3 proteins and thereby promotes FOXO1 nuclear accumulation and transcription factor activity, leading to cell death of postmitotic neurons (PubMed:18356527). The phosphorylation of beta-tubulins regulates microtubule dynamics during mitosis (PubMed:16371510). NEDD1 phosphorylation promotes PLK1-mediated NEDD1 phosphorylation and subsequent targeting of the gamma-tubulin ring complex (gTuRC) to the centrosome, an important step for spindle formation (PubMed:19509060). In addition, CC2D1A phosphorylation regulates CC2D1A spindle pole localization and association with SCC1/RAD21 and centriole cohesion during mitosis (PubMed:20171170). The phosphorylation of Bcl-xL/BCL2L1 after prolongated G2 arrest upon DNA damage triggers apoptosis (PubMed:19917720). In contrast, CASP8 phosphorylation during mitosis prevents its activation by proteolysis and subsequent apoptosis (PubMed:20937773). This phosphorylation occurs in cancer cell lines, as well as in primary breast tissues and lymphocytes (PubMed:20937773). EZH2 phosphorylation promotes H3K27me3 maintenance and epigenetic gene silencing (PubMed:20935635). CALD1 phosphorylation promotes Schwann cell migration during peripheral nerve regeneration (By similarity). CDK1-cyclin-B complex phosphorylates NCKAP5L and mediates its dissociation from centrosomes during mitosis (PubMed:26549230). Regulates the amplitude of the cyclic expression of the core clock gene BMAL1 by phosphorylating its transcriptional repressor NR1D1, and this phosphorylation is necessary for SCF(FBXW7)-mediated ubiquitination and proteasomal degradation of NR1D1 (PubMed:27238018). Phosphorylates EML3 at 'Thr-881' which is essential for its interaction with HAUS augmin-like complex and TUBG1 (PubMed:30723163). Phosphorylates CGAS during mitosis, leading to its inhibition, thereby preventing CGAS activation by self DNA during mitosis (PubMed:32351706). Phosphorylates SKA3 on multiple sites during mitosis which promotes SKA3 binding to the NDC80 complex and anchoring of the SKA complex to kinetochores, to enable stable attachment of mitotic spindle microtubules to kinetochores (PubMed:28479321, PubMed:31804178, PubMed:32491969)\n(Microbial infection) Acts as a receptor for hepatitis C virus (HCV) in hepatocytes and facilitates its cell entry","source":"project UniProt records20261017/18"},{"partner":"CDK2","hgnc":"HGNC:1771","core":true,"core_annotation":{"hgnc":"HGNC:1771","symbol_at_source":"CDK2","accession":"P24941","function":"Histone modification write","target":"histone","pmids":["15753125"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":580,"hub_weight":0.2817180849095055,"quality":0.65,"programmes":["pubmed:36736316"],"pmids":["36736316"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus, Cajal body; Cytoplasm; Endosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase involved in the control of the cell cycle; essential for meiosis, but dispensable for mitosis (PubMed:10499802, PubMed:10884347, PubMed:10995386, PubMed:10995387, PubMed:11051553, PubMed:11113184, PubMed:12944431, PubMed:15800615, PubMed:17495531, PubMed:19966300, PubMed:20935635, PubMed:21262353, PubMed:21596315, PubMed:28216226, PubMed:28666995). Phosphorylates CABLES1, CTNNB1, CDK2AP2, ERCC6, NBN, USP37, p53/TP53, NPM1, CDK7, RB1, BRCA2, MYC, NPAT, SUV39H1, EZH2 (PubMed:10499802, PubMed:10995386, PubMed:10995387, PubMed:11051553, PubMed:11113184, PubMed:12944431, PubMed:15800615, PubMed:19966300, PubMed:20935635, PubMed:21262353, PubMed:21596315, PubMed:24728993, PubMed:28216226). Triggers duplication of centrosomes and DNA (PubMed:11051553). Acts at the G1-S transition to promote the E2F transcriptional program and the initiation of DNA synthesis, and modulates G2 progression; controls the timing of entry into mitosis/meiosis by controlling the subsequent activation of cyclin B/CDK1 by phosphorylation, and coordinates the activation of cyclin B/CDK1 at the centrosome and in the nucleus (PubMed:18372919, PubMed:19238148, PubMed:19561645). Crucial role in orchestrating a fine balance between cellular proliferation, cell death, and DNA repair in embryonic stem cells (ESCs) (PubMed:18372919, PubMed:19238148, PubMed:19561645). Activated by the CDK-activating kinase (CAK) complex consisting of CDK7, cyclin-H/CCNH and MAT1, which is a master regulator of CDK activity (PubMed:41100585). Activity of CDK2 is maximal during S phase and G2; activated by interaction with cyclin E during the early stages of DNA synthesis to permit G1-S transition, and subsequently activated by cyclin A2 (cyclin A1 in germ cells) during the late stages of DNA replication to drive the transition from S phase to mitosis, the G2 phase (PubMed:18372919, PubMed:19238148, PubMed:19561645). EZH2 phosphorylation promotes H3K27me3 maintenance and epigenetic gene silencing (PubMed:20935635). Cyclin E/CDK2 prevents oxidative stress-mediated Ras-induced senescence by phosphorylating MYC (PubMed:19966300). Involved in G1-S phase DNA damage checkpoint that prevents cells with damaged DNA from initiating mitosis; regulates homologous recombination-dependent repair by phosphorylating BRCA2, this phosphorylation is low in S phase when recombination is active, but increases as cells progress towards mitosis (PubMed:15800615, PubMed:20195506, PubMed:21319273). In response to DNA damage, double-strand break repair by homologous recombination a reduction of CDK2-mediated BRCA2 phosphorylation (PubMed:15800615). Involved in regulation of telomere repair by mediating phosphorylation of NBN (PubMed:28216226). Phosphorylation of RB1 disturbs its interaction with E2F1 (PubMed:10499802). NPM1 phosphorylation by cyclin E/CDK2 promotes its dissociates from unduplicated centrosomes, thus initiating centrosome duplication (PubMed:11051553). Cyclin E/CDK2-mediated phosphorylation of NPAT at G1-S transition and until prophase stimulates the NPAT-mediated activation of histone gene transcription during S phase (PubMed:10995386, PubMed:10995387). Required for vitamin D-mediated growth inhibition by being itself inactivated (PubMed:20147522). Involved in the nitric oxide- (NO) mediated signaling in a nitrosylation/activation-dependent manner (PubMed:20079829). USP37 is activated by phosphorylation and thus triggers G1-S transition (PubMed:21596315). CTNNB1 phosphorylation regulates insulin internalization (PubMed:21262353). Phosphorylates FOXP3 and negatively regulates its transcriptional activity and protein stability (By similarity). Phosphorylates ERCC6 which is essential for its chromatin remodeling activity at DNA double-strand breaks (PubMed:29203878). Acts as a regulator of the phosphatidylinositol 3-kinase/protein kinase B signal transduction by mediating phosphorylation of the C-terminus of protein kinase B (PKB/AKT1 and PKB/AKT2), promoting its activation (PubMed:24670654)","source":"project UniProt records20261017/18"},{"partner":"PKN1","hgnc":"HGNC:9405","core":true,"core_annotation":{"hgnc":"HGNC:9405","symbol_at_source":"PKN1","accession":"Q16512","function":"Histone modification write","target":"histone","pmids":["18066052"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":110,"hub_weight":0.5590169943749475,"quality":0.75,"programmes":["pubmed:32814053"],"pmids":["32814053"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Endosome; Cell membrane; Cleavage furrow; Midbody","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"PKC-related serine/threonine-protein kinase involved in various processes such as regulation of the intermediate filaments of the actin cytoskeleton, cell migration, tumor cell invasion and transcription regulation. Part of a signaling cascade that begins with the activation of the adrenergic receptor ADRA1B and leads to the activation of MAPK14. Regulates the cytoskeletal network by phosphorylating proteins such as VIM and neurofilament proteins NEFH, NEFL and NEFM, leading to inhibit their polymerization. Phosphorylates 'Ser-575', 'Ser-637' and 'Ser-669' of MAPT/Tau, lowering its ability to bind to microtubules, resulting in disruption of tubulin assembly. Acts as a key coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and specifically mediating phosphorylation of 'Thr-11' of histone H3 (H3T11ph), a specific tag for epigenetic transcriptional activation that promotes demethylation of histone H3 'Lys-9' (H3K9me) by KDM4C/JMJD2C. Phosphorylates HDAC5, HDAC7 and HDAC9, leading to impair their import in the nucleus. Phosphorylates 'Thr-38' of PPP1R14A, 'Ser-159', 'Ser-163' and 'Ser-170' of MARCKS, and GFAP. Able to phosphorylate RPS6 in vitro","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZNF853":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C4orf54":{"coreEvidence":[{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"},{"partner":"CUL4A","hgnc":"HGNC:2554","core":true,"core_annotation":{"hgnc":"HGNC:2554","symbol_at_source":"CUL4A","accession":"Q13619","function":"Histone modification write","target":"histone","pmids":["16678110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":588,"hub_weight":0.2799462554779272,"quality":0.65,"programmes":["pubmed:21145461"],"pmids":["21145461"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Core component of multiple cullin-RING-based E3 ubiquitin-protein ligase complexes which mediate the ubiquitination of target proteins (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620, PubMed:30166453, PubMed:33854232, PubMed:33854239). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1 (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). The functional specificity of the E3 ubiquitin-protein ligase complex depends on the variable substrate recognition component (PubMed:14578910, PubMed:14739464, PubMed:15448697, PubMed:15548678, PubMed:15811626, PubMed:16678110, PubMed:17041588, PubMed:24209620). DCX(DET1-COP1) directs ubiquitination of JUN (PubMed:14739464). DCX(DDB2) directs ubiquitination of XPC (PubMed:15811626). DCX(DDB2) ubiquitinates histones H3-H4 and is required for efficient histone deposition during replication-coupled (H3.1) and replication-independent (H3.3) nucleosome assembly, probably by facilitating the transfer of H3 from ASF1A/ASF1B to other chaperones involved in histone deposition (PubMed:16678110, PubMed:17041588, PubMed:24209620). DCX(DTL) plays a role in PCNA-dependent polyubiquitination of CDT1 and MDM2-dependent ubiquitination of p53/TP53 in response to radiation-induced DNA damage and during DNA replication (PubMed:14578910, PubMed:15448697, PubMed:15548678). DCX(DTL) directs autoubiquitination of DTL (PubMed:23478445). In association with DDB1 and SKP2 probably is involved in ubiquitination of CDKN1B/p27kip (PubMed:16537899). Is involved in ubiquitination of HOXA9 (PubMed:14609952). The DDB1-CUL4A-DTL E3 ligase complex regulates the circadian clock function by mediating the ubiquitination and degradation of CRY1 (PubMed:26431207). The DCX(ERCC8) complex (also named CSA complex) plays a role in transcription-coupled repair (TCR) (PubMed:12732143, PubMed:32355176, PubMed:38316879). A number of DCX complexes (containing either TRPC4AP or DCAF12 as substrate-recognition component) are part of the DesCEND (destruction via C-end degrons) pathway, which recognizes a C-degron located at the extreme C terminus of target proteins, leading to their ubiquitination and degradation (PubMed:29779948). The DCX(AMBRA1) complex is a master regulator of the transition from G1 to S cell phase by mediating ubiquitination of phosphorylated cyclin-D (CCND1, CCND2 and CCND3) (PubMed:33854232, PubMed:33854239). The DCX(AMBRA1) complex also acts as a regulator of Cul5-RING (CRL5) E3 ubiquitin-protein ligase complexes by mediating ubiquitination and degradation of Elongin-C (ELOC) component of CRL5 complexes (PubMed:30166453). With CUL4B, contributes to ribosome biogenesis (PubMed:26711351)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SH3TC1":{"coreEvidence":[{"partner":"SMARCA2","hgnc":"HGNC:11098","core":true,"core_annotation":{"hgnc":"HGNC:11098","symbol_at_source":"SMARCA2","accession":"P51531","function":"Histone modification read, TF","target":"histone, DNA","pmids":["22464331"],"complexes":"BAF, nBAF, npBAF, WINAC, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":275,"hub_weight":0.3922322702763681,"quality":0.65,"programmes":["pubmed:31753913"],"pmids":["31753913"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner. Binds DNA non-specifically (PubMed:15075294, PubMed:22952240, PubMed:26601204). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SATL1":{"coreEvidence":[{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TEX52":{"coreEvidence":[{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LEKR1":{"coreEvidence":[{"partner":"EZH2","hgnc":"HGNC:3527","core":true,"core_annotation":{"hgnc":"HGNC:3527","symbol_at_source":"EZH2","accession":"Q15910","function":"Histone modification write, Polycomb group (PcG) protein","target":"histone","pmids":["19026781"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1062,"hub_weight":0.21204723241999274,"quality":0.65,"programmes":["pubmed:27634302"],"pmids":["27634302"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the PRC2/EED-EZH2 complex, a Polycomb group (PcG) complex that methylates 'Lys-9' (H3K9me) and 'Lys-27' (H3K27me) of histone H3, leading to transcriptional repression of the affected target gene (PubMed:14532106, PubMed:15225548, PubMed:15385962, PubMed:16618801, PubMed:16936726, PubMed:17344414, PubMed:22323599, PubMed:24474760, PubMed:26581166, PubMed:30026490, PubMed:30923826). Able to mono-, di- and trimethylate 'Lys-27' of histone H3 to form H3K27me1, H3K27me2 and H3K27me3, respectively (PubMed:15231737, PubMed:17210787, PubMed:18285464, PubMed:22323599, PubMed:30923826). Displays a preference for substrates with less methylation, loses activity when progressively more methyl groups are incorporated into H3K27, H3K27me0 > H3K27me1 > H3K27me2 (PubMed:22323599, PubMed:30923826). Compared to EZH1-containing complexes, it is more abundant in embryonic stem cells and plays a major role in forming H3K27me3, which is required for embryonic stem cell identity and proper differentiation (PubMed:19026781). The PRC2/EED-EZH2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems (PubMed:16357870, PubMed:17200670). Genes repressed by the PRC2/EED-EZH2 complex include HOXC8, HOXA9, MYT1, CDKN2A and retinoic acid target genes (PubMed:16179254, PubMed:18086877, PubMed:20935635). EZH2 can also methylate non-histone proteins such as the transcription factor GATA4 and the nuclear receptor RORA (PubMed:23063525). Regulates the circadian clock via histone methylation at the promoter of the circadian genes (PubMed:16717091). Essential for the CRY1/2-mediated repression of the transcriptional activation of PER1/2 by the CLOCK-BMAL1 heterodimer; involved in the di and trimethylation of 'Lys-27' of histone H3 on PER1/2 promoters which is necessary for the CRY1/2 proteins to inhibit transcription (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"OGFOD3":{"coreEvidence":[{"partner":"FOXA1","hgnc":"HGNC:5021","core":true,"core_annotation":{"hgnc":"HGNC:5021","symbol_at_source":"FOXA1","accession":"P55317","function":"Chromatin remodeling, TF","target":"chromatin, DNA","pmids":["22406422"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":397,"hub_weight":0.33445003104532556,"quality":0.65,"programmes":["pubmed:30572598"],"pmids":["30572598"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription factor that is involved in embryonic development, establishment of tissue-specific gene expression and regulation of gene expression in differentiated tissues. Is thought to act as a 'pioneer' factor opening the compacted chromatin for other proteins through interactions with nucleosomal core histones and thereby replacing linker histones at target enhancer and/or promoter sites. Binds DNA with the consensus sequence 5'-[AC]A[AT]T[AG]TT[GT][AG][CT]T[CT]-3' (By similarity). Proposed to play a role in translating the epigenetic signatures into cell type-specific enhancer-driven transcriptional programs. Its differential recruitment to chromatin is dependent on distribution of histone H3 methylated at 'Lys-5' (H3K4me2) in estrogen-regulated genes. Involved in the development of multiple endoderm-derived organ systems such as liver, pancreas, lung and prostate; FOXA1 and FOXA2 seem to have at least in part redundant roles (By similarity). Modulates the transcriptional activity of nuclear hormone receptors. Is involved in ESR1-mediated transcription; required for ESR1 binding to the NKX2-1 promoter in breast cancer cells; binds to the RPRM promoter and is required for the estrogen-induced repression of RPRM. Involved in regulation of apoptosis by inhibiting the expression of BCL2. Involved in cell cycle regulation by activating expression of CDKN1B, alone or in conjunction with BRCA1. Originally described as a transcription activator for a number of liver genes such as AFP, albumin, tyrosine aminotransferase, PEPCK, etc. Interacts with the cis-acting regulatory regions of these genes. Involved in glucose homeostasis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MYRFL":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZFR2":{"coreEvidence":[{"partner":"APEX1","hgnc":"HGNC:587","core":true,"core_annotation":{"hgnc":"HGNC:587","symbol_at_source":"APEX1","accession":"P27695","function":"DNA modification cofactor","target":"DNA","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":428,"hub_weight":0.32342311367657545,"quality":0.35,"programmes":["pubmed:26344197"],"pmids":["26344197"],"assays":["cofractionation"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Nucleus speckle; Endoplasmic reticulum; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional protein that plays a central role in the cellular response to oxidative stress. The two major activities of APEX1 are DNA repair and redox regulation of transcriptional factors (PubMed:11118054, PubMed:11452037, PubMed:15831793, PubMed:18439621, PubMed:18579163, PubMed:21762700, PubMed:24079850, PubMed:8355688, PubMed:9108029, PubMed:9560228). Functions as an apurinic/apyrimidinic (AP) endodeoxyribonuclease in the base excision repair (BER) pathway of DNA lesions induced by oxidative and alkylating agents. Initiates repair of AP sites in DNA by catalyzing hydrolytic incision of the phosphodiester backbone immediately adjacent to the damage, generating a single-strand break with 5'-deoxyribose phosphate and 3'-hydroxyl ends. Also incises at AP sites in the DNA strand of DNA/RNA hybrids, single-stranded DNA regions of R-loop structures, and single-stranded RNA molecules (PubMed:15380100, PubMed:16617147, PubMed:18439621, PubMed:19123919, PubMed:19188445, PubMed:19934257, PubMed:20699270, PubMed:21762700, PubMed:24079850, PubMed:8932375, PubMed:8995436, PubMed:9804799). Operates at switch sites of immunoglobulin (Ig) constant regions where it mediates Ig isotype class switch recombination. Processes AP sites induced by successive action of AICDA and UNG. Generates staggered nicks in opposite DNA strands resulting in the formation of double-strand DNA breaks that are finally resolved via non-homologous end joining repair pathway (By similarity). Has 3'-5' exodeoxyribonuclease activity on mismatched deoxyribonucleotides at the 3' termini of nicked or gapped DNA molecules during short-patch BER (PubMed:11832948, PubMed:1719477). Possesses DNA 3' phosphodiesterase activity capable of removing lesions (such as phosphoglycolate and 8-oxoguanine) blocking the 3' side of DNA strand breaks (PubMed:15831793, PubMed:7516064). Also acts as an endoribonuclease involved in the control of single-stranded RNA metabolism. Plays a role in regulating MYC mRNA turnover by preferentially cleaving in between UA and CA dinucleotides of the MYC coding region determinant (CRD). In association with NMD1, plays a role in the rRNA quality control process during cell cycle progression (PubMed:19188445, PubMed:19401441, PubMed:21762700). Acts as a loading factor for POLB onto non-incised AP sites in DNA and stimulates the 5'-terminal deoxyribose 5'-phosphate (dRp) excision activity of POLB (PubMed:9207062). Exerts reversible nuclear redox activity to regulate DNA binding affinity and transcriptional activity of transcriptional factors by controlling the redox status of their DNA-binding domain, such as the FOS/JUN AP-1 complex after exposure to IR (PubMed:10023679, PubMed:11118054, PubMed:11452037, PubMed:18579163, PubMed:8355688, PubMed:9108029). Involved in calcium-dependent down-regulation of parathyroid hormone (PTH) expression by binding to negative calcium response elements (nCaREs). Together with HNRNPL or the dimer XRCC5/XRCC6, associates with nCaRE, acting as an activator of transcriptional repression (PubMed:11809897, PubMed:14633989, PubMed:8621488). May also play a role in the epigenetic regulation of gene expression by participating in DNA demethylation (PubMed:21496894). Stimulates the YBX1-mediated MDR1 promoter activity, when acetylated at Lys-6 and Lys-7, leading to drug resistance (PubMed:18809583). Plays a role in protection from granzyme-mediated cellular repair leading to cell death (PubMed:18179823). Binds DNA and RNA. Associates, together with YBX1, on the MDR1 promoter. Together with NPM1, associates with rRNA (PubMed:19188445, PubMed:19401441, PubMed:20699270)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"CAPS2":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SHE":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"OXNAD1":{"coreEvidence":[{"partner":"EZH2","hgnc":"HGNC:3527","core":true,"core_annotation":{"hgnc":"HGNC:3527","symbol_at_source":"EZH2","accession":"Q15910","function":"Histone modification write, Polycomb group (PcG) protein","target":"histone","pmids":["19026781"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1062,"hub_weight":0.21204723241999274,"quality":0.65,"programmes":["pubmed:36517590"],"pmids":["36517590"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the PRC2/EED-EZH2 complex, a Polycomb group (PcG) complex that methylates 'Lys-9' (H3K9me) and 'Lys-27' (H3K27me) of histone H3, leading to transcriptional repression of the affected target gene (PubMed:14532106, PubMed:15225548, PubMed:15385962, PubMed:16618801, PubMed:16936726, PubMed:17344414, PubMed:22323599, PubMed:24474760, PubMed:26581166, PubMed:30026490, PubMed:30923826). Able to mono-, di- and trimethylate 'Lys-27' of histone H3 to form H3K27me1, H3K27me2 and H3K27me3, respectively (PubMed:15231737, PubMed:17210787, PubMed:18285464, PubMed:22323599, PubMed:30923826). Displays a preference for substrates with less methylation, loses activity when progressively more methyl groups are incorporated into H3K27, H3K27me0 > H3K27me1 > H3K27me2 (PubMed:22323599, PubMed:30923826). Compared to EZH1-containing complexes, it is more abundant in embryonic stem cells and plays a major role in forming H3K27me3, which is required for embryonic stem cell identity and proper differentiation (PubMed:19026781). The PRC2/EED-EZH2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems (PubMed:16357870, PubMed:17200670). Genes repressed by the PRC2/EED-EZH2 complex include HOXC8, HOXA9, MYT1, CDKN2A and retinoic acid target genes (PubMed:16179254, PubMed:18086877, PubMed:20935635). EZH2 can also methylate non-histone proteins such as the transcription factor GATA4 and the nuclear receptor RORA (PubMed:23063525). Regulates the circadian clock via histone methylation at the promoter of the circadian genes (PubMed:16717091). Essential for the CRY1/2-mediated repression of the transcriptional activation of PER1/2 by the CLOCK-BMAL1 heterodimer; involved in the di and trimethylation of 'Lys-27' of histone H3 on PER1/2 promoters which is necessary for the CRY1/2 proteins to inhibit transcription (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PLAC8L1":{"coreEvidence":[{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SPATA31H1":{"coreEvidence":[{"partner":"NUCLEOLIN","hgnc":"HGNC:7667","core":true,"core_annotation":{"hgnc":"HGNC:7667","symbol_at_source":"NCL","accession":"P19338","function":"Histone chaperone","target":"histone, DNA, RNA","pmids":["16601700"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":695,"hub_weight":0.2590638800754199,"quality":0.65,"programmes":["pubmed:38334954"],"pmids":["38334954"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Nucleolin is the major nucleolar protein of growing eukaryotic cells. It is found associated with intranucleolar chromatin and pre-ribosomal particles. It induces chromatin decondensation by binding to histone H1. It is thought to play a role in pre-rRNA transcription and ribosome assembly. May play a role in the process of transcriptional elongation. Binds RNA oligonucleotides with 5'-UUAGGG-3' repeats more tightly than the telomeric single-stranded DNA 5'-TTAGGG-3' repeats","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
